using System.Reflection;

namespace D47.Core.Knowledge;

/// <summary>The shipped table of starter systems, generated by <c>tools/gen-starters.py</c> from journals.</summary>
public static class StarterSystemTable
{
    private const string ResourceName = "D47.Core.StarterSystems";

    private static readonly Lazy<HashSet<string>> Loaded =
        new(() => Read(typeof(StarterSystemTable).GetTypeInfo().Assembly.GetManifestResourceStream(ResourceName)),
            LazyThreadSafetyMode.ExecutionAndPublication);

    public static IReadOnlyCollection<string> Names => Loaded.Value;

    /// <summary>Whether this is a starter system, which a Commander loses access to early on.</summary>
    public static bool Contains(string? system) =>
        system is { Length: > 0 } named && Loaded.Value.Contains(named);

    /// <summary>Reads table text: one name per line, lines starting with '#' ignored.</summary>
    public static HashSet<string> Parse(string text)
    {
        using var reader = new StringReader(text);
        return Read(reader);
    }

    private static HashSet<string> Read(Stream? stream)
    {
        if (stream is null)
        {
            return new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        }

        using (stream)
        using (var reader = new StreamReader(stream))
        {
            return Read(reader);
        }
    }

    private static HashSet<string> Read(TextReader reader)
    {
        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        while (reader.ReadLine() is { } line)
        {
            if (line.Length > 0 && line[0] != '#')
            {
                names.Add(line);
            }
        }

        return names;
    }
}
